contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller, address newOwner) public {
        require(caller != address(0));
        require(newOwner != address(0));

        address ownerBefore = c.owner();

        bool reverted;
        try c.setOwner(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address ownerAfter = c.owner();

        if (msg.sender == ownerBefore) {
            assert(!reverted);
            assert(ownerAfter == newOwner);
        } else {
            assert(reverted);
            assert(ownerAfter == ownerBefore);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address newOwner) public {
        require(newOwner != address(0));

        address ownerBefore = c.owner();
        bool isOwner = (msg.sender == ownerBefore);

        bool reverted;
        bool success;
        try c.setOwner(newOwner) returns (bool s) {
            success = s;
            reverted = false;
        } catch {
            reverted = true;
        }

        address ownerAfter = c.owner();

        assert(
            (isOwner && !reverted && success && ownerAfter == newOwner)
            || (!isOwner && reverted && ownerAfter == ownerBefore)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address newOwner) public {
        require(msg.sender == address(this));

        address ownerBefore = c.owner();
        require(ownerBefore == address(this));

        bool success;
        bool reverted;
        try c.setOwner(newOwner) returns (bool s) {
            success = s;
            reverted = false;
        } catch {
            reverted = true;
        }

        address ownerAfter = c.owner();

        assert(!reverted && success && ownerAfter == newOwner);
    }

    receive() external payable {}
}

